// A session in a running programme (spec 2026-11-04 sections 7, 8, 10): generated by the engine from
// the run's stage, on the run's own track, at the adopted reference, stamped with its slot; finished
// without touching ordinary progression; discarded with a recorded disposition.
import { afterAll, beforeAll, describe, expect, it, vi } from 'vitest'
import { buildSessionExposures, missingOneRms, occurrenceFor } from './session-start.js'
import { buildCombinedExposures } from './session-merge.js'
import { historyAsOf } from './backfill.js'
import { buildCompletedSession } from './finish-session.js'
import { entriesForExposures } from './session-ui-adapter.js'
import { migratedFixture } from './test-fixtures.js'
import { isWarmupRow } from './workout-model.js'
import { mergeStates } from './sync-merge.js'
import { contentHash, defaultPlanRule, generatePrescription, slotFor, slotInputs } from './prescription/index.js'
import { programmeView, startProgramme, saveProgramme, setLegacyWeek, legacyWeeksOf, discardEvents } from './programmes.js'
import { convertLegacyProgramme } from '../../../api/migration/programme-upgrade.js'
import { LIB_BY_ID } from '../../../api/coach/core/library.js'

// Wednesday 2026-10-21, local noon: the run below started on its Monday.
beforeAll(() => { vi.useFakeTimers({ toFake: ['Date'] }); vi.setSystemTime(new Date(2026, 9, 21, 12, 0)) })
afterAll(() => { vi.useRealTimers() })

const BENCH = '0025', SQUAT = '0043'
const clone = v => JSON.parse(JSON.stringify(v))
const occ = (exId, oid, rid, sets, reps, weight) => occurrenceFor(exId, { sets, reps, weight }, { id: oid, routineId: rid, preset: 'linear' })
const orm = (id, value, capturedAt) => ({ id, exerciseId: BENCH, value, unit: 'kg', source: 'manual', capturedAt })
const profile = (over = {}) => ({
  engineSchemaVersion: 2, engineContractRevision: 1, unit: 'kg', weekStart: 1, restSec: 90,
  routines: [
    { id: 'A', name: 'Day A', ex: [occ(BENCH, 'a-bench', 'A', 3, 5, 60), occ(SQUAT, 'a-squat', 'A', 3, 5, 80)] },
    { id: 'B', name: 'Day B', ex: [occ(SQUAT, 'b-squat', 'B', 3, 8, 70)] },
  ],
  workouts: [], prescriptions: {}, progression: {}, oneRepMaxes: { b100: orm('b100', 100, '2026-10-01T00:00:00.000Z') },
  week: { 1: ['A'] }, programmes: {}, programme: null, ...over,
})
const BLOCK = { id: 'P', name: 'Strength block', at: 1, days: { 1: ['A'], 4: ['B'] }, weeks: [{ rpe: 7, t: { [BENCH]: { pct: 75 } } }, { rpe: 8, t: { [BENCH]: { pct: 80 } } }, { deload: true }] }
const ADVANCE = { onFailure: 'advance', onSkipped: 'advance' }
function running(S = profile(), block = BLOCK, startedOn = '2026-10-19') {
  S.programmes = { [block.id]: convertLegacyProgramme(block, { routines: S.routines, catalogue: LIB_BY_ID }) }
  const policies = Object.fromEntries(S.programmes[block.id].tracks.map(t => [t.id, ADVANCE]))
  expect(startProgramme(S, block.id, { policies, end: 'stop', today: startedOn, now: Date.parse(startedOn + 'T08:00:00Z') })).toEqual({ ok: true })
  return S
}
const routine = (S, id) => S.routines.find(r => r.id === id)
// A session of routine `rid` at `at`, every work row done as prescribed, saved into S.
function session(S, rid, at, { done = true } = {}) {
  const now = Date.parse(at)
  const exposures = buildSessionExposures(S, routine(S, rid), { now, newId: s => s })
  const A = { id: 'w:' + at, d: at.slice(0, 10), start: now, routineIds: [rid], exposures, entries: entriesForExposures(exposures, S.prescriptions) }
  if (done) A.entries.forEach(e => e.sets.forEach(row => { if (!isWarmupRow(row)) row.done = true }))
  return A
}
function finish(S, A) {
  const out = buildCompletedSession(A, S, { end: A.start + 3600000, newId: s => s, unit: 'kg' })
  S.workouts = [...S.workouts, out.session]
  S.progression = { ...S.progression, ...out.progression }
  return out
}
const work = (S, x) => S.prescriptions[x.prescriptionId].rows.map(r => r.load?.value)
const benchOf = A => A.exposures.find(x => x.exerciseId === BENCH)

describe('a session of a running programme', () => {
  it('a programme session generates from the stage rule; no prescription is patched after generation', () => {
    // A heavier estimate in history (100 × 5, Epley 116.7) is what the old overlay resolved %1RM against.
    const S = running(profile({ workouts: migratedFixture({ unit: 'kg', workouts: [{ id: 'old', d: '2026-10-01', start: 1, routineIds: ['A'], entries: [{ id: BENCH, rid: 'A', target: { id: BENCH, sets: 3, reps: 5, weight: 100 }, sets: [{ w: 100, r: 5, done: true }] }] }] }).workouts }))
    const A = session(S, 'A', '2026-10-21T10:00:00Z')
    const x = benchOf(A), p = S.prescriptions[x.prescriptionId]
    expect(work(S, x)).toEqual([75, 75, 75])   // 75 % of the adopted 100, not of 116.7
    expect(x.programme).toMatchObject({ slot: 'p1:a0:a-bench', stage: 's1', attempt: 1, role: 'work', ref: { id: 'b100', value: 100 }, effort: { mode: 'advisory', rpe: 7 } })
    expect(p.provenance.programme).toEqual(x.programme)
    expect(x.trackId).toBe(`run:${S.programme.runId}:${x.programme.trackId}:a-bench`)
    // The same engine call gives the same targets: only provenance was added, under a fresh hash.
    const view = programmeView({ ...S, workouts: S.workouts.filter(w => w.id !== 'never') })
    const { assignment } = slotFor({ view, run: view.run, rid: 'A', oid: 'a-bench', date: '2026-10-21' })
    const inputs = slotInputs({ view, run: view.run, assignment, occRule: routine(S, 'A').ex[0].rule })
    expect(p.ruleSnapshot).toEqual(inputs.rule)
    const direct = generatePrescription({ id: p.id, now: p.generatedAt, ...inputs, warmupFloor: p.warmupFloor ?? 0, equipment: 'barbell' })
    expect(p.rows.map(r => [r.load, r.reps])).toEqual(direct.rows.map(r => [r.load, r.reps]))
    expect(p.prefill).toEqual(direct.prefill)
    const { contentHash: hash, ...body } = p
    expect(hash).toBe(contentHash(body))
  })

  it('a percent stage uses the adopted 100 kg even after a 110 kg estimate appears', () => {
    const S = running()
    S.oneRepMaxes = { ...S.oneRepMaxes, b110: orm('b110', 110, '2026-10-20T00:00:00.000Z') }
    const A = session(S, 'A', '2026-10-21T10:00:00Z')
    expect(work(S, benchOf(A))).toEqual([75, 75, 75])
    expect(benchOf(A).programme.ref.id).toBe('b100')
  })

  it('a backdated session fills its own week s appointment, else it is extra', () => {
    // Started a week earlier: today is week 2, last week (week 1) has closed.
    const S = running(profile(), BLOCK, '2026-10-12')
    // Monday of this week, logged on Wednesday: this week's Monday appointment, as work.
    const mon = buildSessionExposures(S, routine(S, 'A'), { now: Date.parse('2026-10-19T17:00:00Z'), newId: s => 'mon:' + s })
    expect(benchOf({ exposures: mon }).programme).toMatchObject({ slot: 'p2:a0:a-bench', stage: 's2', role: 'work' })
    expect(benchOf({ exposures: mon }).excludedFromProgression).toBe(false)
    // A Monday of the closed week: logged as extra, earning no slot and moving nothing.
    const old = buildSessionExposures(S, routine(S, 'A'), { now: Date.parse('2026-10-13T17:00:00Z'), newId: s => 'old:' + s })
    expect(benchOf({ exposures: old }).programme).toMatchObject({ slot: 'p1:a0:a-bench', role: 'extra' })
    expect(benchOf({ exposures: old }).excludedFromProgression).toBe(true)
  })

  it('logged into the past (beginBackfill), a session reads the run as it stands and keeps what it adopts', () => {
    // On Wednesday, Monday's A is logged afterwards, generated from the history as of Monday
    // (backfill.js historyAsOf), as beginBackfill does.
    const start = Date.parse('2026-10-19T17:00:00Z')
    const backfill = S => buildCombinedExposures(S, ['A', 'R'], { now: start, newId: s => 'bf:' + s, history: historyAsOf(S, { d: '2026-10-19', start }) })
    const pct = { occurrenceId: 'r-bench', exerciseId: BENCH, rule: defaultPlanRule('autoregulated', { id: 'r-bench', exerciseId: BENCH, routineId: 'R', sets: { min: 3, max: 3 }, reps: { min: 5, max: 5 }, load: { mode: 'percent_1rm', percent: 80 } }) }
    const withR = S => ({ ...S, routines: [...S.routines, { id: 'R', name: 'Standalone', ex: [pct, occ(SQUAT, 'r-squat', 'R', 3, 5, 80)] }] })
    // Tuesday's A already holds this week's Monday appointment: the late Monday is extra, never a second credit.
    const S = running(withR(profile()))
    finish(S, session(S, 'A', '2026-10-20T10:00:00Z'))
    finish(S, session(S, 'R', '2026-10-20T11:00:00Z'))
    const late = backfill(S)
    expect(benchOf(late).programme).toMatchObject({ slot: 'p1:a0:a-bench', role: 'extra' })
    // Its prescriptions come from the history before its day (#284): Tuesday's squat moved R's track to 82.5.
    expect(work(S, late.exposures.find(x => x.occurrenceId === 'r-squat'))).toEqual([80, 80, 80])
    expect(programmeView(S).tracks['t:P:a-bench'].slots.find(x => x.id === 'p1:a0:a-bench').exposureId).toBe(S.workouts[0].exposures[0].exposureId)
    // What it adopts is the profile's own: the run's first reference and the occurrence's.
    const T = running(withR(profile({ oneRepMaxes: {} })))
    T.oneRepMaxes = { b90: orm('b90', 90, '2026-10-21T09:00:00.000Z') }
    const out = backfill(T)
    expect(benchOf(out).programme).toMatchObject({ slot: 'p1:a0:a-bench', role: 'work', ref: { id: 'b90' } })
    expect(Object.values(T.programmeEvents).filter(e => e.type === 'reference')).toMatchObject([{ trackId: 't:P:a-bench', ref: { id: 'b90' }, from: null }])
    expect(programmeView(T).tracks['t:P:a-bench'].nextRef.id).toBe('b90')
    expect(T.routines.find(r => r.id === 'R').ex[0].ref).toMatchObject({ id: 'b90' })
    expect(work(T, out.exposures.find(x => x.routineId === 'R'))).toEqual([72.5, 72.5, 72.5])   // 80 % of 90, on the 2.5 grid
  })

  it('a programme exposure never advances ordinary progression; its run replays instead', () => {
    const S = running()
    const before = clone(S.progression)
    const out = finish(S, session(S, 'A', '2026-10-21T10:00:00Z'))
    expect(out.progression).toEqual({})
    expect(S.progression).toEqual(before)
    const tv = programmeView(S).tracks['t:P:a-squat']
    expect(tv.slots.find(s => s.id === 'p1:a0:a-squat')).toMatchObject({ outcome: 'succeeded' })
    expect(tv.values['a-squat'].state.values.load).toMatchObject({ value: 82.5 })   // the run's own track moved on
    // Nor does a merge's replay write the run's track into ordinary progression.
    expect(Object.keys(mergeStates(S, clone(S)).progression ?? {}).filter(k => k.startsWith('run:'))).toEqual([])
  })

  it('discard with a done work row records a failed discard; without one a skip', () => {
    const S = running()
    const A = session(S, 'A', '2026-10-21T10:00:00Z', { done: false })
    const bench = A.entries.find(e => e.exposureId === benchOf(A).exposureId)
    bench.sets.find(row => !isWarmupRow(row)).done = true
    const view = programmeView(S, null, A)
    const events = discardEvents(A, view, Date.parse('2026-10-21T11:00:00Z'))
    expect(events.map(e => [e.type, e.slot, e.worked])).toEqual([['discard', 'p1:a0:a-bench', true], ['discard', 'p1:a0:a-squat', false]])
    S.programmeEvents = Object.fromEntries(events.map(e => [e.id, e]))
    const tracks = programmeView(S).tracks
    expect(tracks['t:P:a-bench'].slots[0]).toMatchObject({ outcome: 'failed', reasons: ['abandoned'] })
    expect(tracks['t:P:a-squat'].slots[0]).toMatchObject({ outcome: 'skipped', reasons: ['discard'] })
  })

  it('saving the running programme appends an amend event; the current week keeps its targets', () => {
    const S = running(profile(), { ...BLOCK, days: { 1: ['A'], 4: ['A'] } })
    finish(S, session(S, 'A', '2026-10-19T10:00:00Z'))
    const def = S.programmes.P
    saveProgramme(S, setLegacyWeek(setLegacyWeek(def, 0, { rpe: 7, t: { [BENCH]: { pct: 85 } } }, S), 1, { rpe: 8, t: { [BENCH]: { pct: 90 } } }, S), Date.parse('2026-10-20T09:00:00Z'))
    const amends = Object.values(S.programmeEvents).filter(e => e.type === 'amend')
    expect(amends).toHaveLength(1)
    expect(amends[0].def.rev).toBe(def.rev + 1)
    expect(legacyWeeksOf(amends[0].def)[0].t[BENCH].pct).toBe(85)
    // Thursday of the started week keeps its 75 %; next week takes the edit.
    const thu = session(S, 'A', '2026-10-22T10:00:00Z')
    expect(work(S, benchOf(thu))).toEqual([75, 75, 75])
    finish(S, thu)
    vi.setSystemTime(new Date(2026, 9, 26, 12, 0))
    try { expect(work(S, benchOf(session(S, 'A', '2026-10-26T10:00:00Z')))).toEqual([90, 90, 90]) }
    finally { vi.setSystemTime(new Date(2026, 9, 21, 12, 0)) }
  })

  it('first use of a percent rule captures its reference into the occurrence', () => {
    const pct = { occurrenceId: 'p-bench', exerciseId: BENCH, rule: defaultPlanRule('autoregulated', { id: 'p-bench', exerciseId: BENCH, routineId: 'R', sets: { min: 3, max: 3 }, reps: { min: 5, max: 5 }, load: { mode: 'percent_1rm', percent: 80 } }) }
    const S = profile({ routines: [{ id: 'R', name: 'Bench', ex: [pct] }] })
    const [x] = buildSessionExposures(S, S.routines[0], { now: Date.parse('2026-10-21T10:00:00Z'), newId: s => s })
    expect(S.routines[0].ex[0].ref).toMatchObject({ id: 'b100', value: 100 })
    expect(work(S, x)).toEqual([80, 80, 80])
    // A newer 1RM changes nothing until it is accepted.
    S.oneRepMaxes = { ...S.oneRepMaxes, b110: orm('b110', 110, '2026-10-20T00:00:00.000Z') }
    const [y] = buildSessionExposures(S, S.routines[0], { now: Date.parse('2026-10-21T11:00:00Z'), newId: s => 'y' + s })
    expect(work(S, y)).toEqual([80, 80, 80])
    expect(S.routines[0].ex[0].ref.id).toBe('b100')
  })

  it('a track with no 1RM yet asks for one, and its first session adopts the one entered', () => {
    const S = running(profile({ oneRepMaxes: {} }))
    expect(S.programmeRuns[S.programme.runId].tracks['t:P:a-bench'].ref).toBeUndefined()
    expect(missingOneRms(S, [routine(S, 'A')])).toEqual([BENCH])
    S.oneRepMaxes = { b90: orm('b90', 90, '2026-10-21T09:00:00.000Z') }
    expect(missingOneRms(S, [routine(S, 'A')])).toEqual([])
    const A = session(S, 'A', '2026-10-21T10:00:00Z')
    expect(Object.values(S.programmeEvents)).toMatchObject([{ type: 'reference', trackId: 't:P:a-bench', ref: { id: 'b90' }, from: null }])
    expect(work(S, benchOf(A))).toEqual([67.5, 67.5, 67.5])
    expect(benchOf(A).programme.ref.id).toBe('b90')
  })

  it('a week option of 2 % incline reaches the exposure; the routine keeps its own 1 %', () => {
    const run = migratedFixture({ unit: 'kg', routines: [{ id: 'C', name: 'Run', ex: [{ id: '3666', mode: 'cardio', sets: 3, min: 5, speed: 8, incline: 1 }] }], workouts: [] }).routines[0]
    const S = profile({ routines: [run] })
    const def = convertLegacyProgramme({ id: 'Q', name: 'Hills', at: 1, days: { 3: ['C'] }, weeks: [{}] }, { routines: S.routines, catalogue: LIB_BY_ID })
    const oid = run.ex[0].occurrenceId
    def.tracks[0].stages[0].targets[oid] = { own: 'inherit', options: { incline: 2 } }
    S.programmes = { Q: def }
    expect(startProgramme(S, 'Q', { policies: { [def.tracks[0].id]: ADVANCE }, end: 'stop', today: '2026-10-19' })).toEqual({ ok: true })
    const [x] = buildSessionExposures(S, S.routines[0], { now: Date.parse('2026-10-21T10:00:00Z'), newId: s => s })
    expect(x.incline).toBe(2)
    expect(x.programme).toMatchObject({ role: 'work' })
    expect(S.prescriptions[x.prescriptionId].ruleSnapshot.options).toEqual({ incline: 2 })
    expect(S.routines[0].ex[0].cardio.incline).toBe(1)
  })
})
